const fmtBRL = (v) =>
  new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(v) || 0);
const fmtPct = (v) => `${(Number(v) || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%`;
const todayISO = () => new Date().toISOString().slice(0, 10);
const monthKey = (iso) => (iso ? iso.slice(0, 7) : null);
const monthLabel = (ym) => {
  if (!ym) return "—";
  const [y, m] = ym.split("-");
  return `${["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"][Number(m) - 1]}/${y}`;
};

function commissionRateFor(base, tiers) {
  if (!tiers || tiers.length === 0) return null;
  const sorted = [...tiers].sort((a, b) => a.min - b.min);
  // min é inclusivo, max é exclusivo — evita que um valor na fronteira exata
  // entre duas faixas (ex.: 50% da meta com faixas 0–50 e 50–70) caia por
  // engano na faixa de baixo.
  const hit = sorted.find((t) => base >= t.min && (t.max === null || t.max === "" || base < t.max));
  if (hit) return hit.percentual;
  // valor abaixo do mínimo de todas as faixas cadastradas: nenhuma comissão ainda
  if (base < sorted[0].min) return 0;
  return sorted[sorted.length - 1].percentual;
}

function daysUntil(dateISO) {
  const today = new Date(todayISO() + "T00:00:00");
  const target = new Date(dateISO + "T00:00:00");
  return Math.round((target - today) / 86400000);
}

function recebimentoStatus(rec) {
  if (rec.recebido) return "recebido";
  const d = daysUntil(rec.dataVencimento);
  if (d < 0) return "atrasado";
  if (d === 0) return "hoje";
  if (d <= 7) return "proximo";
  return "futuro";
}

