/* ---------------------------- Permissions ---------------------------- */

const ROLE_LABEL = { diretora: "Diretora Comercial", lider: "Líder Comercial", colaborador: "Colaborador" };

function teamColaboradorIds(db, user) {
  if (!user || user.papel === "diretora") return null; // null = sem restrição
  if (user.papel === "lider") {
    const ids = new Set([user.colaboradorId]);
    db.collaborators.forEach((c) => {
      if (c.liderId === user.colaboradorId) ids.add(c.id);
    });
    return ids;
  }
  return new Set([user.colaboradorId]); // colaborador: só ele mesmo
}

function visibleHonorarios(db, user) {
  const team = teamColaboradorIds(db, user);
  if (team === null) return db.honorarios;
  return db.honorarios.filter((h) => team.has(h.colaboradorId) || team.has(h.liderId));
}

/* ---------------------- Comissão mensal por meta (consultor) ----------------------
   Modelo: a comissão do consultor não é mais por lançamento — é calculada uma vez
   por mês, sobre o total de honorários fechados naquele mês (pela data do crédito).
   O % de comissão (tabela de faixas) incide sobre o honorário líquido do mês; o
   bônus é um valor fixo pelo atingimento da meta ou da super meta (o maior vale
   sozinho, não somam). O líder continua recebendo 3% fixo por lançamento, à parte.
------------------------------------------------------------------------------- */

function honorarioLiquido(h) {
  return (Number(h.valorHonorario) || 0) - (Number(h.valorParceiro) || 0) - (Number(h.imposto) || 0);
}

function computeMonthlyConsultor(db, colaboradorId, ym) {
  const honorariosMes = db.honorarios.filter((h) => h.colaboradorId === colaboradorId && monthKey(h.dataCredito) === ym);
  const bruto = honorariosMes.reduce((s, h) => s + (Number(h.valorHonorario) || 0), 0);
  const liquido = honorariosMes.reduce((s, h) => s + honorarioLiquido(h), 0);
  const metas = db.metas || {};
  const metaMensal = metas.metaMensal || 0;
  const superMeta = metas.superMeta || 0;
  const pct = metaMensal > 0 ? (bruto / metaMensal) * 100 : 0;
  const rate = commissionRateFor(pct, db.tiers);
  const comissao = rate !== null ? liquido * (rate / 100) : 0;
  let bonus = 0;
  if (superMeta > 0 && bruto >= superMeta) bonus = metas.bonusSuperMeta || 0;
  else if (metaMensal > 0 && bruto >= metaMensal) bonus = metas.bonusMeta || 0;
  return { colaboradorId, ym, bruto, liquido, pct, rate, comissao, bonus, total: comissao + bonus, count: honorariosMes.length };
}

// pares únicos (colaborador, mês) presentes num conjunto de honorários já filtrado
function distinctConsultorMonths(honorarios) {
  const map = new Map();
  honorarios.forEach((h) => {
    const ym = monthKey(h.dataCredito);
    if (!ym || !h.colaboradorId) return;
    const key = `${h.colaboradorId}|${ym}`;
    if (!map.has(key)) map.set(key, { colaboradorId: h.colaboradorId, ym });
  });
  return [...map.values()];
}

/* ---------------------------- Gamificação: esforço, ranking, roleta ---------------------------- */

// segunda-feira da semana da data informada (ISO yyyy-mm-dd) -> chave "yyyy-mm-dd"
function weekKeyOf(iso) {
  if (!iso) return null;
  const d = new Date(iso + "T00:00:00");
  if (isNaN(d.getTime())) return null;
  const day = (d.getDay() + 6) % 7; // 0 = segunda
  d.setDate(d.getDate() - day);
  return d.toISOString().slice(0, 10);
}
function addDaysISO(iso, days) {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
function mondayOfToday() {
  return weekKeyOf(todayISO());
}
function weekLabel(mondayIso) {
  if (!mondayIso) return "—";
  const end = addDaysISO(mondayIso, 6);
  const fmt = (iso) => {
    const [, m, dd] = iso.split("-");
    return `${dd}/${m}`;
  };
  return `${fmt(mondayIso)} a ${fmt(end)}`;
}

// ---- motor de pontuação (esforço + resultado), no espírito do "Jogo de Metas" ----
// Cada colaborador tem um "diário" por dia (yyyy-mm-dd -> {metricaId: valor}), juntando:
//  - lançamentos manuais (prospecção, contatos, reuniões, documentação, propostas…)
//  - indicadores "auto", calculados a partir dos honorários já lançados em Operações
//    (operações aprovadas, crédito liberado, honorário gerado) — sem digitar de novo.
function ativasMetricas(db) {
  return (db.metricas || []).filter((m) => m.ativo !== false);
}
function daysOfColaborador(db, colaboradorId) {
  const out = {};
  (db.lancamentos || [])
    .filter((l) => l.colaboradorId === colaboradorId && l.data)
    .forEach((l) => {
      out[l.data] = out[l.data] || {};
      Object.entries(l.valores || {}).forEach(([mid, v]) => {
        out[l.data][mid] = (out[l.data][mid] || 0) + (Number(v) || 0);
      });
    });
  const autoMetricas = ativasMetricas(db).filter((m) => m.fonte === "auto");
  if (autoMetricas.length) {
    (db.honorarios || [])
      .filter((h) => h.colaboradorId === colaboradorId && h.dataCredito)
      .forEach((h) => {
        const d = h.dataCredito;
        out[d] = out[d] || {};
        autoMetricas.forEach((m) => {
          let v = 0;
          if (m.autoKey === "operacoesFechadas") v = 1;
          else if (m.autoKey === "valorLiberado") v = Number(h.valorLiberado) || 0;
          else if (m.autoKey === "honorarioGerado") v = Number(h.valorHonorario) || 0;
          out[d][m.id] = (out[d][m.id] || 0) + v;
        });
      });
  }
  return out;
}
function sumRangeAdv(db, colaboradorId, from, to) {
  const days = daysOfColaborador(db, colaboradorId);
  const t = {};
  Object.entries(days).forEach(([d, v]) => {
    if (d >= from && d <= to) Object.entries(v).forEach(([k, val]) => (t[k] = (t[k] || 0) + (Number(val) || 0)));
  });
  return t;
}
function unitPts(m, v) {
  v = Number(v) || 0;
  if (!v || !m.pts) return 0;
  if (m.tipo === "tempo") return (v / 60) * m.pts;
  if (m.tipo === "valor") return (v / 1000) * m.pts;
  return v * m.pts;
}
function scoreForAdv(db, t, periodo) {
  const r = { unit: 0, bonus: 0, esf: 0, res: 0, hit: 0, total: 0 };
  ativasMetricas(db).forEach((m) => {
    const u = unitPts(m, t[m.id]);
    r.unit += u;
    r[m.categoria === "resultado" ? "res" : "esf"] += u;
    if (m.periodo === periodo) {
      r.total++;
      if (m.meta > 0 && (t[m.id] || 0) >= m.meta) {
        r.hit++;
        r.bonus += Number(m.bonus) || 0;
        r[m.categoria === "resultado" ? "res" : "esf"] += Number(m.bonus) || 0;
      }
    }
  });
  return r;
}
function weekBonusOnlyAdv(db, colaboradorId, monday) {
  const t = sumRangeAdv(db, colaboradorId, monday, addDaysISO(monday, 6));
  const r = { bonus: 0, esf: 0, res: 0 };
  ativasMetricas(db).forEach((m) => {
    if (m.periodo === "semanal" && m.meta > 0 && (t[m.id] || 0) >= m.meta) {
      r.bonus += Number(m.bonus) || 0;
      r[m.categoria === "resultado" ? "res" : "esf"] += Number(m.bonus) || 0;
    }
  });
  return r;
}
function monthBonusOnlyAdv(db, colaboradorId, ym) {
  const t = sumRangeAdv(db, colaboradorId, ym + "-01", ym + "-31");
  const r = { bonus: 0, esf: 0, res: 0 };
  ativasMetricas(db).forEach((m) => {
    if (m.periodo === "mensal" && m.meta > 0 && (t[m.id] || 0) >= m.meta) {
      r.bonus += Number(m.bonus) || 0;
      r[m.categoria === "resultado" ? "res" : "esf"] += Number(m.bonus) || 0;
    }
  });
  return r;
}
function weekResultAdv(db, colaboradorId, monday) {
  const t = sumRangeAdv(db, colaboradorId, monday, addDaysISO(monday, 6));
  const s = scoreForAdv(db, t, "semanal");
  return { t, ...s, pts: Math.round(s.unit + s.bonus), esf: Math.round(s.esf), res: Math.round(s.res) };
}
function mondaysInMonth(ym) {
  let d = ym + "-01";
  while (new Date(d + "T00:00:00").getDay() !== 1) d = addDaysISO(d, 1);
  const out = [];
  while (d.slice(0, 7) === ym) {
    out.push(d);
    d = addDaysISO(d, 7);
  }
  return out;
}
function monthResultAdv(db, colaboradorId, ym) {
  const t = sumRangeAdv(db, colaboradorId, ym + "-01", ym + "-31");
  const s = scoreForAdv(db, t, "mensal");
  let wb = 0,
    we = 0,
    wr = 0;
  mondaysInMonth(ym).forEach((mon) => {
    const b = weekBonusOnlyAdv(db, colaboradorId, mon);
    wb += b.bonus;
    we += b.esf;
    wr += b.res;
  });
  return { t, ...s, pts: Math.round(s.unit + s.bonus + wb), esf: Math.round(s.esf + we), res: Math.round(s.res + wr) };
}
function presentWeeks(db, colaboradorId) {
  return [...new Set(Object.keys(daysOfColaborador(db, colaboradorId)).map(weekKeyOf))];
}
function presentMonths(db, colaboradorId) {
  return [...new Set(Object.keys(daysOfColaborador(db, colaboradorId)).map(monthKey))];
}
// XP total (nunca diminui): soma os pontos "unitários" de cada dia lançado + os bônus de cada
// semana/mês em que houve alguma atividade registrada.
function xpTotalAdv(db, colaboradorId) {
  const days = daysOfColaborador(db, colaboradorId);
  let unit = 0;
  Object.values(days).forEach((v) => ativasMetricas(db).forEach((m) => (unit += unitPts(m, v[m.id]))));
  let bonus = 0;
  presentWeeks(db, colaboradorId).forEach((mon) => (bonus += weekBonusOnlyAdv(db, colaboradorId, mon).bonus));
  presentMonths(db, colaboradorId).forEach((ym) => (bonus += monthBonusOnlyAdv(db, colaboradorId, ym).bonus));
  return Math.round(unit + bonus);
}
function levelForAdv(db, xp) {
  const L = ((db.niveis && db.niveis.length ? db.niveis : DEFAULT_NIVEIS()) || []).slice().sort((a, b) => a.xp - b.xp);
  let i = 0;
  L.forEach((l, k) => {
    if (xp >= l.xp) i = k;
  });
  const cur = L[i],
    nxt = L[i + 1];
  return { cur, nxt, idx: i, all: L, pct: nxt ? Math.min(100, ((xp - cur.xp) / (nxt.xp - cur.xp)) * 100) : 100 };
}
function streakMetricAdv(db) {
  return ativasMetricas(db).find((m) => (Number(m.dailyMin) || 0) > 0);
}
function isBusinessDay(iso) {
  const d = new Date(iso + "T00:00:00").getDay();
  return d !== 0 && d !== 6;
}
function streakOfAdv(db, colaboradorId) {
  const m = streakMetricAdv(db);
  if (!m) return { cur: 0, best: 0, m: null };
  const days = daysOfColaborador(db, colaboradorId);
  const ok = (d) => (Number((days[d] || {})[m.id]) || 0) >= m.dailyMin;
  let cur = 0,
    d = todayISO();
  if (!ok(d)) d = addDaysISO(d, -1);
  for (let i = 0; i < 500; i++) {
    if (!isBusinessDay(d)) {
      d = addDaysISO(d, -1);
      continue;
    }
    if (ok(d)) {
      cur++;
      d = addDaysISO(d, -1);
    } else break;
  }
  const ds = Object.keys(days).sort();
  let best = 0,
    run = 0;
  if (ds.length) {
    let x = ds[0];
    const end = todayISO();
    let guard = 0;
    while (x <= end && guard++ < 2000) {
      if (isBusinessDay(x)) {
        if (ok(x)) {
          run++;
          best = Math.max(best, run);
        } else if (x !== end) run = 0;
      }
      x = addDaysISO(x, 1);
    }
  }
  return { cur, best: Math.max(best, cur), m };
}
function rankForAdv(db, colaboradores, periodo, chave) {
  return colaboradores.map((c) => ({ c, r: periodo === "semana" ? weekResultAdv(db, c.id, chave) : monthResultAdv(db, c.id, chave) }));
}
function weekFeatsAdv(db, colaboradorId, todosColaboradores) {
  const weeks = presentWeeks(db, colaboradorId);
  const curMon = mondayOfToday();
  const effW = ativasMetricas(db).filter((m) => m.categoria === "esforco" && m.periodo === "semanal" && m.meta > 0);
  let full = 0,
    top = 0;
  weeks.forEach((mon) => {
    const t = weekResultAdv(db, colaboradorId, mon).t;
    if (effW.length && effW.every((m) => (t[m.id] || 0) >= m.meta)) full++;
    if (mon < curMon) {
      const rk = rankForAdv(db, todosColaboradores, "semana", mon).slice().sort((a, b) => b.r.pts - a.r.pts);
      if (rk[0] && rk[0].c.id === colaboradorId && rk[0].r.pts > 0 && (!rk[1] || rk[1].r.pts < rk[0].r.pts)) top++;
    }
  });
  return { full, top };
}
function badgesForAdv(db, colaboradorId, todosColaboradores) {
  const days = daysOfColaborador(db, colaboradorId);
  const all = {};
  const monthsV = {};
  const credM = (db.metricas || []).find((m) => m.autoKey === "valorLiberado");
  const opsM = (db.metricas || []).find((m) => m.autoKey === "operacoesFechadas");
  Object.entries(days).forEach(([d, v]) => {
    Object.entries(v).forEach(([k, val]) => (all[k] = (all[k] || 0) + (Number(val) || 0)));
    if (credM && v[credM.id]) monthsV[d.slice(0, 7)] = (monthsV[d.slice(0, 7)] || 0) + (Number(v[credM.id]) || 0);
  });
  const { full, top } = weekFeatsAdv(db, colaboradorId, todosColaboradores);
  const st = streakOfAdv(db, colaboradorId);
  const maxV = Math.max(0, ...Object.values(monthsV), 0);
  const list = [];
  if (opsM) list.push({ ic: "🔑", nome: "Primeira operação", desc: "Fechou a primeira operação aprovada", got: (all[opsM.id] || 0) >= 1 });
  if (st.m) list.push({ ic: "🔥", nome: "Disciplina", desc: `5 dias úteis seguidos batendo o mínimo diário de ${st.m.nome.toLowerCase()}`, got: st.best >= 5, prog: `recorde: ${st.best}` });
  if (st.m) list.push({ ic: "🏃", nome: "Maratonista", desc: "20 dias úteis seguidos batendo o mínimo diário", got: st.best >= 20, prog: `recorde: ${st.best}` });
  list.push({ ic: "✅", nome: "Semana completa", desc: "Bateu todas as metas semanais de esforço", got: full >= 1, prog: full ? `${full}x` : "" });
  list.push({ ic: "👑", nome: "Topo da semana", desc: "Fechou uma semana em 1º lugar no ranking", got: top >= 1, prog: top ? `${top}x` : "" });
  if (credM) list.push({ ic: "💎", nome: "Clube do milhão", desc: "R$ 1 milhão em crédito liberado em um único mês", got: maxV >= 1000000 });
  if (opsM) list.push({ ic: "🥈", nome: "Consistência", desc: "10 operações aprovadas no total", got: (all[opsM.id] || 0) >= 10, prog: `${all[opsM.id] || 0}/10` });
  return list;
}

// ---- giros da roleta: XP acumulado / limiar, semana completa, topo da semana, extras manuais ----
function spinInfoAdv(db, colaboradorId) {
  const roleta = db.roleta || {};
  const xp = xpTotalAdv(db, colaboradorId);
  const feats = weekFeatsAdv(db, colaboradorId, db.collaborators || []);
  const per = Number(roleta.xpPorGiro) || 0;
  const fromXp = per > 0 ? Math.floor(xp / per) : 0;
  const fromTop = roleta.topoDaSemana ? feats.top : 0;
  const fromFull = roleta.semanaCompleta ? feats.full : 0;
  const bonus = (db.girosExtras || []).filter((g) => g.colaboradorId === colaboradorId).reduce((s, g) => s + (Number(g.qtd) || 0), 0);
  const earned = fromXp + fromTop + fromFull + bonus;
  const used = (db.spins || []).filter((s) => s.colaboradorId === colaboradorId && s.tipo !== "denovo").length;
  return { earned, used, available: Math.max(0, earned - used), fromXp, fromTop, fromFull, bonus, nextXp: per > 0 ? per - (xp % per) : null, xp };
}
function girosGanhos(db, colaboradorId) {
  return spinInfoAdv(db, colaboradorId).earned;
}
function girosUsados(db, colaboradorId) {
  return spinInfoAdv(db, colaboradorId).used;
}
function girosDisponiveis(db, colaboradorId) {
  return spinInfoAdv(db, colaboradorId).available;
}

function premioAwardedCount(db, premioId) {
  return (db.spins || []).filter((s) => s.premioId === premioId).length;
}

// prêmios que ainda podem sair: ativos, peso>0 e (sem limite de estoque ou estoque ainda disponível)
function premiosElegiveis(db) {
  return (db.roleta.premios || []).filter((p) => {
    if (p.ativo === false) return false;
    if ((Number(p.peso) || 0) <= 0) return false;
    if (p.estoque && Number(p.estoque) > 0 && premioAwardedCount(db, p.id) >= Number(p.estoque)) return false;
    return true;
  });
}

// sorteio ponderado entre prêmios elegíveis
function sortearPremio(elegiveis) {
  const ativos = elegiveis || [];
  if (!ativos.length) return null;
  const total = ativos.reduce((s, p) => s + (Number(p.peso) || 0), 0);
  let r = Math.random() * total;
  for (const p of ativos) {
    r -= Number(p.peso) || 0;
    if (r <= 0) return p;
  }
  return ativos[ativos.length - 1];
}

/* ---------------------------- UI atoms ---------------------------- */

function Field({ label, children, hint }) {
  return (
    <label className="field">
      <span className="field-label">{label}</span>
      {children}
      {hint && <span className="field-hint">{hint}</span>}
    </label>
  );
}
function TextInput(props) {
  return <input className="input" {...props} />;
}
function MoneyInput({ value, onChange, className = "", style, step, type, ...props }) {
  // Currency-formatted input: shows "R$ 1.234,56" (thousands separators +
  // comma decimals) while the person types, but keeps onChange firing with a
  // plain numeric string (e.g. "1234.56") in e.target.value — the digits the
  // person types, in the order they type them, exactly like a normal
  // <input type="number"> — so existing handlers and stored data don't change.
  const display = (() => {
    if (value === "" || value === null || value === undefined) return "";
    const s = String(value);
    const neg = s.trim().startsWith("-");
    const [intRaw, decRaw] = s.replace("-", "").split(".");
    const intDigits = (intRaw || "0").replace(/\D/g, "") || "0";
    const grouped = intDigits.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    const dec = decRaw !== undefined ? "," + decRaw.replace(/\D/g, "") : "";
    return (neg ? "-" : "") + grouped + dec;
  })();
  const handleChange = (e) => {
    const raw = e.target.value;
    const neg = raw.trim().startsWith("-");
    let cleaned = raw.replace(/[^\d,]/g, "");
    const firstComma = cleaned.indexOf(",");
    if (firstComma !== -1) {
      cleaned = cleaned.slice(0, firstComma) + "." + cleaned.slice(firstComma + 1).replace(/,/g, "").slice(0, 2);
    }
    if (!cleaned || cleaned === ".") {
      onChange({ target: { value: "" } });
      return;
    }
    onChange({ target: { value: (neg ? "-" : "") + cleaned } });
  };
  return (
    <div className={`money-input-wrap ${className}`} style={style}>
      <span className="money-prefix">R$</span>
      <input
        className="input money-input"
        type="text"
        inputMode="decimal"
        value={display}
        onChange={handleChange}
        placeholder="0,00"
        {...props}
      />
    </div>
  );
}
function Select({ children, ...props }) {
  return (
    <select className="input" {...props}>
      {children}
    </select>
  );
}
function Btn({ variant = "primary", children, ...props }) {
  return (
    <button className={`btn btn-${variant}`} {...props}>
      {children}
    </button>
  );
}
function ConfirmDelete({ onConfirm }) {
  const [confirming, setConfirming] = useState(false);
  if (confirming) {
    return (
      <span className="confirm-row">
        <button className="btn btn-danger btn-sm" onClick={onConfirm}>
          <Check size={13} /> Excluir
        </button>
        <button className="btn btn-ghost btn-sm" onClick={() => setConfirming(false)}>
          <X size={13} />
        </button>
      </span>
    );
  }
  return (
    <button className="icon-btn" onClick={() => setConfirming(true)} title="Excluir">
      <Trash2 size={15} />
    </button>
  );
}
function EmptyState({ text }) {
  return (
    <div className="empty-state">
      <AlertCircle size={16} />
      <span>{text}</span>
    </div>
  );
}
function Tag({ children, tone }) {
  return <span className={`tag ${tone ? `tag-${tone}` : ""}`}>{children}</span>;
}
function RowActions({ onEdit, onDelete }) {
  return (
    <span className="actions">
      <button className="icon-btn" onClick={onEdit} title="Editar">
        <Pencil size={14} />
      </button>
      <ConfirmDelete onConfirm={onDelete} />
    </span>
  );
}

/* ---------------------------- Login ---------------------------- */

export function LoginScreen({ users, onLogin, seeded, remote }) {
  const [usuario, setUsuario] = useState("");
  const [senha, setSenha] = useState("");
  const [error, setError] = useState("");

  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (remote) {
      setBusy(true);
      setError("");
      const msg = await remote.signIn(usuario.trim(), senha);
      setBusy(false);
      if (msg) setError(msg);
      return;
    }
    const found = users.find((u) => u.usuario === usuario.trim() && u.senha === senha);
    if (!found) {
      setError("Usuário ou senha incorretos.");
      return;
    }
    setError("");
    onLogin(found);
  };

  return (
    <div className="login-screen">
      <div className="login-aside">
        <div className="login-aside-glow" aria-hidden="true" />
        <div className="login-aside-grid" aria-hidden="true" />
        <img src={LOGO_FULL_WHITE} alt="Adventus Capital" className="login-logo" />
        <p className="login-tagline">Crédito estruturado com precisão — operações, comissões e performance em um só lugar.</p>
      </div>
      <div className="login-main">
      <form className="login-card" onSubmit={submit}>
        <h1 className="login-title">Acessar o sistema</h1>
        {seeded && !remote && (
          <p className="panel-note">
            Primeiro acesso: usuário <strong>admin</strong>, senha <strong>admin</strong>. Troque
            depois em Cadastros → Usuários.
          </p>
        )}
        <Field label={remote ? "E-mail" : "Usuário"}>
          <TextInput type={remote ? "email" : "text"} value={usuario} onChange={(e) => setUsuario(e.target.value)} required autoFocus />
        </Field>
        <Field label="Senha">
          <TextInput type="password" value={senha} onChange={(e) => setSenha(e.target.value)} required />
        </Field>
        {error && <p className="login-error">{error}</p>}
        <Btn type="submit" disabled={busy}>{busy ? "Entrando…" : "Entrar"}</Btn>
      </form>
      </div>
    </div>
  );
}

