function UsersPanel({ users, collaborators, onAdd, onEdit, onDelete }) {
  const blank = { nome: "", usuario: "", senha: "", papel: "lider", colaboradorId: "" };
  const [form, setForm] = useState(blank);
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState(blank);
  const lideres = collaborators.filter((c) => c.papel === "lider");
  const colaboradoresComuns = collaborators.filter((c) => c.papel === "colaborador");

  return (
    <div className="panel">
      <h3 className="panel-title">Usuários e permissões</h3>
      <p className="panel-note">
        Diretora Comercial vê e edita tudo. Líder Comercial vê a própria equipe. Colaborador vê só os próprios lançamentos e comissões.
      </p>
      <form
        className="form-grid"
        onSubmit={(e) => {
          e.preventDefault();
          if (!form.nome.trim() || !form.usuario.trim() || !form.senha) return;
          if ((form.papel === "lider" || form.papel === "colaborador") && !form.colaboradorId) return;
          onAdd({ nome: form.nome.trim(), usuario: form.usuario.trim(), senha: form.senha, papel: form.papel, colaboradorId: form.papel !== "diretora" ? form.colaboradorId : "" });
          setForm(blank);
        }}
      >
        <UserFormFields value={form} onChange={setForm} editing={false} lideres={lideres} colaboradoresComuns={colaboradoresComuns} />
        <div className="form-actions">
          <Btn type="submit">
            <Plus size={14} /> Adicionar usuário
          </Btn>
        </div>
      </form>
      {users.length === 0 ? (
        <EmptyState text="Nenhum usuário cadastrado." />
      ) : (
        <table className="table">
          <thead>
            <tr>
              <th>Nome</th>
              <th>Usuário</th>
              <th>Papel</th>
              <th>Equipe</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.id}>
                <td colSpan={editingId === u.id ? 5 : 1}>
                  {editingId === u.id ? (
                    <div className="form-grid" style={{ padding: "8px 0" }}>
                      <UserFormFields value={editForm} onChange={setEditForm} editing={true} lideres={lideres} colaboradoresComuns={colaboradoresComuns} />
                      <div className="form-actions">
                        <Btn
                          type="button"
                          onClick={() => {
                            const patch = { ...editForm };
                            if (!patch.senha) delete patch.senha;
                            if (patch.papel === "diretora") patch.colaboradorId = "";
                            onEdit(u.id, patch);
                            setEditingId(null);
                          }}
                        >
                          <Check size={14} /> Salvar
                        </Btn>
                        <Btn type="button" variant="ghost" onClick={() => setEditingId(null)}>
                          Cancelar
                        </Btn>
                      </div>
                    </div>
                  ) : (
                    u.nome
                  )}
                </td>
                {editingId !== u.id && (
                  <>
                    <td>{u.usuario}</td>
                    <td>{ROLE_LABEL[u.papel]}</td>
                    <td>{u.colaboradorId ? collaborators.find((c) => c.id === u.colaboradorId)?.nome || "—" : "—"}</td>
                    <td className="actions">
                      <RowActions
                        onEdit={() => {
                          setEditingId(u.id);
                          setEditForm({ ...u, senha: "" });
                        }}
                        onDelete={() => onDelete(u.id)}
                      />
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function CadastrosPage({ db, mutate, user }) {
  const isDiretora = user.papel === "diretora";
  const [tab, setTab] = useState("instituicoes");
  const tabs = [
    { id: "instituicoes", label: "Instituições financeiras", icon: Landmark },
    { id: "categorias", label: "Categorias", icon: TagIcon },
    { id: "clientes", label: "Clientes", icon: Users },
    { id: "parceiros", label: "Parceiros", icon: Handshake },
    { id: "colaboradores", label: "Colaboradores", icon: Users },
    ...(isDiretora ? [{ id: "tabela", label: "Metas e Comissão", icon: Percent }] : []),
    ...(isDiretora ? [{ id: "usuarios", label: "Usuários", icon: ShieldCheck }] : []),
  ];

  const delFrom = (key) => (id) => mutate((d) => ({ ...d, [key]: d[key].filter((x) => x.id !== id) }));
  const editIn = (key) => (id, patch) => mutate((d) => ({ ...d, [key]: d[key].map((x) => (x.id === id ? { ...x, ...patch } : x)) }));

  const team = teamColaboradorIds(db, user);
  const visibleCollaborators = team === null ? db.collaborators : db.collaborators.filter((c) => team.has(c.id));

  return (
    <div>
      <div className="subtabs">
        {tabs.map((t) => (
          <button key={t.id} className={`subtab ${tab === t.id ? "subtab-active" : ""}`} onClick={() => setTab(t.id)}>
            <t.icon size={14} />
            {t.label}
          </button>
        ))}
      </div>

      {tab === "instituicoes" && (
        <InstitutionsList
          items={db.institutions}
          categories={db.institutionCategories}
          onAdd={(nome, categoriaId) => mutate((d) => ({ ...d, institutions: [...d.institutions, { id: uid(), nome, categoriaId }] }))}
          onEdit={editIn("institutions")}
          onDelete={delFrom("institutions")}
        />
      )}
      {tab === "categorias" && (
        <EditableSimpleList
          title="Categorias de instituição financeira"
          note="Use para agrupar instituições — ex.: Banco, Fintech, Fundo de investimento, Financeira."
          items={db.institutionCategories}
          onAdd={(nome) => mutate((d) => ({ ...d, institutionCategories: [...d.institutionCategories, { id: uid(), nome }] }))}
          onEdit={(id, nome) => editIn("institutionCategories")(id, { nome })}
          onDelete={delFrom("institutionCategories")}
          placeholder="Nome da categoria"
        />
      )}
      {tab === "clientes" && (
        <EditableSimpleList
          title="Clientes"
          items={db.clients}
          onAdd={(nome) => mutate((d) => ({ ...d, clients: [...d.clients, { id: uid(), nome }] }))}
          onEdit={(id, nome) => editIn("clients")(id, { nome })}
          onDelete={delFrom("clients")}
          placeholder="Nome do cliente"
        />
      )}
      {tab === "parceiros" && (
        <PartnersList
          items={db.partners}
          onAdd={(nome, percentual, base) => mutate((d) => ({ ...d, partners: [...d.partners, { id: uid(), nome, percentual, base }] }))}
          onEdit={editIn("partners")}
          onDelete={delFrom("partners")}
        />
      )}
      {tab === "colaboradores" && (
        <CollaboratorsList
          items={visibleCollaborators}
          allCollaborators={db.collaborators}
          canManageRole={isDiretora}
          scopeNote={!isDiretora ? "Você só vê e adiciona colaboradores da sua própria equipe." : null}
          onAdd={(nome, papel, liderId) =>
            mutate((d) => ({
              ...d,
              collaborators: [...d.collaborators, { id: uid(), nome, papel: isDiretora ? papel : "colaborador", liderId: isDiretora ? liderId : user.colaboradorId }],
            }))
          }
          onEdit={editIn("collaborators")}
          onDelete={delFrom("collaborators")}
        />
      )}
      {tab === "tabela" && isDiretora && (
        <>
          <MetasPanel metas={db.metas || {}} onSave={(metas) => mutate((d) => ({ ...d, metas }))} />
          <TiersPanel tiers={db.tiers} onAdd={(tier) => mutate((d) => ({ ...d, tiers: [...d.tiers, { id: uid(), ...tier }] }))} onEdit={editIn("tiers")} onDelete={delFrom("tiers")} />
        </>
      )}
      {tab === "usuarios" && isDiretora && (
        <UsersPanel
          users={db.users}
          collaborators={db.collaborators}
          onAdd={(u) => mutate((d) => ({ ...d, users: [...d.users, { id: uid(), ...u }] }))}
          onEdit={editIn("users")}
          onDelete={delFrom("users")}
        />
      )}
    </div>
  );
}

