function OperacaoCompletaForm({ db, editingOp, editingHon, onSave, onCancel, user }) {
  const ownRecord = db.collaborators.find((c) => c.id === user.colaboradorId);
  const isSelfScoped = user.papel === "lider" || user.papel === "colaborador";
  const team = teamColaboradorIds(db, user);
  const colaboradorOptions = team === null ? db.collaborators : db.collaborators.filter((c) => team.has(c.id));

  const [form, setForm] = useState(() => ({
    // Operação
    numero: editingOp?.numero || "",
    instituicaoId: editingOp?.instituicaoId || "",
    clienteId: editingOp?.clienteId || editingHon?.clienteId || "",
    valorAprovado: editingOp?.valorAprovado ?? "",
    valorAReceber: editingOp?.valorAReceber ?? "",
    dataRecebimentoBanco: editingOp?.dataRecebimentoBanco || "",
    recebidoBanco: editingOp?.recebidoBanco || false,
    // TAC (opcional)
    tacAtivo: editingOp?.tacAtivo || false,
    tacValorGeral: editingOp?.tacValorGeral ?? "",
    tacParceiroNome: editingOp?.tacParceiroNome || "DMX",
    tacPctAdventus: editingOp?.tacPctAdventus ?? 60,
    // Honorário
    modalidade: editingHon?.modalidade || "",
    parceiroId: editingHon?.parceiroId || "",
    dataCredito: editingHon?.dataCredito || todayISO(),
    valorLiberado: editingHon?.valorLiberado ?? "",
    valorHonorario: editingHon?.valorHonorario ?? "",
    valorParceiro: editingHon?.valorParceiro ?? "",
    imposto: editingHon?.imposto ?? "",
    colaboradorId: editingHon?.colaboradorId || (user.papel === "lider" || user.papel === "colaborador" ? user.colaboradorId : ""),
    liderId: editingHon?.liderId || (user.papel === "lider" ? user.colaboradorId : user.papel === "colaborador" ? ownRecord?.liderId || "" : ""),
  }));
  const [impostoTocado, setImpostoTocado] = useState(!!editingHon);

  const recalcParceiro = (merged) => {
    const partner = db.partners.find((p) => p.id === merged.parceiroId);
    if (!partner) return merged;
    // Regra: a comissão do parceiro incide SEMPRE sobre o honorário pago pelo cliente
    // à Adventus (independe do "base" antigo gravado no cadastro do parceiro).
    const base = merged.valorHonorario;
    if (base === "" || base === undefined) return merged;
    return { ...merged, valorParceiro: (Number(base) * (Number(partner.percentual) / 100)).toFixed(2) };
  };
  const recalcImposto = (merged) => {
    if (impostoTocado) return merged;
    const impostoPadrao = db.metas?.impostoPadrao || 0;
    if (merged.valorHonorario === "" || merged.valorHonorario === undefined) return merged;
    return { ...merged, imposto: (Number(merged.valorHonorario) * (impostoPadrao / 100)).toFixed(2) };
  };
  const updateForm = (patch) => setForm((prev) => recalcImposto(recalcParceiro({ ...prev, ...patch })));

  const onValorAprovadoChange = (v) => updateForm({ valorAprovado: v, valorLiberado: form.valorLiberado === "" ? v : form.valorLiberado });

  const selectedPartner = db.partners.find((p) => p.id === form.parceiroId);
  const percentualReceita = form.valorAprovado && form.valorAReceber ? (Number(form.valorAReceber) / Number(form.valorAprovado)) * 100 : 0;
  const pctHonorario = form.valorLiberado && form.valorHonorario ? (Number(form.valorHonorario) / Number(form.valorLiberado)) * 100 : 0;
  const pctParceiro = form.valorHonorario && form.valorParceiro ? (Number(form.valorParceiro) / Number(form.valorHonorario)) * 100 : 0;
  const liquidoPreview = (Number(form.valorHonorario) || 0) - (Number(form.valorParceiro) || 0) - (Number(form.imposto) || 0);
  const comissaoLiderPreview = form.liderId ? liquidoPreview * 0.03 : 0;

  const tacValorAdventus = form.tacAtivo ? (Number(form.tacValorGeral) || 0) * (Number(form.tacPctAdventus) / 100) : 0;
  const tacPctParceiro = 100 - (Number(form.tacPctAdventus) || 0);
  const tacValorParceiro = form.tacAtivo ? (Number(form.tacValorGeral) || 0) * (tacPctParceiro / 100) : 0;

  // Projeção da meta mensal do consultor
  const ym = monthKey(form.dataCredito);
  const outrosDoMes = db.honorarios.filter(
    (h) => h.colaboradorId === form.colaboradorId && monthKey(h.dataCredito) === ym && h.id !== (editingHon && editingHon.id)
  );
  const brutoAcumulado = outrosDoMes.reduce((s, h) => s + (Number(h.valorHonorario) || 0), 0) + (Number(form.valorHonorario) || 0);
  const liquidoAcumulado = outrosDoMes.reduce((s, h) => s + honorarioLiquido(h), 0) + liquidoPreview;
  const metaMensal = db.metas?.metaMensal || 0;
  const superMeta = db.metas?.superMeta || 0;
  const pctMeta = metaMensal > 0 ? (brutoAcumulado / metaMensal) * 100 : 0;
  const rateProjetada = commissionRateFor(pctMeta, db.tiers);
  const comissaoProjetada = rateProjetada !== null ? liquidoAcumulado * (rateProjetada / 100) : null;
  let bonusProjetado = 0;
  if (superMeta > 0 && brutoAcumulado >= superMeta) bonusProjetado = db.metas?.bonusSuperMeta || 0;
  else if (metaMensal > 0 && brutoAcumulado >= metaMensal) bonusProjetado = db.metas?.bonusMeta || 0;

  return (
    <form
      className="panel form-grid"
      onSubmit={(e) => {
        e.preventDefault();
        if (!form.numero || !form.instituicaoId || !form.clienteId || !form.colaboradorId) return;
        onSave({
          operacao: {
            numero: form.numero,
            instituicaoId: form.instituicaoId,
            clienteId: form.clienteId,
            valorAprovado: Number(form.valorAprovado) || 0,
            valorAReceber: Number(form.valorAReceber) || 0,
            dataRecebimentoBanco: form.dataRecebimentoBanco || null,
            recebidoBanco: !!form.recebidoBanco,
            tacAtivo: !!form.tacAtivo,
            tacValorGeral: Number(form.tacValorGeral) || 0,
            tacParceiroNome: form.tacParceiroNome || "DMX",
            tacPctAdventus: Number(form.tacPctAdventus) || 0,
          },
          honorario: {
            clienteId: form.clienteId,
            modalidade: form.modalidade,
            parceiroId: form.parceiroId,
            dataCredito: form.dataCredito,
            valorLiberado: Number(form.valorLiberado) || 0,
            valorHonorario: Number(form.valorHonorario) || 0,
            valorParceiro: Number(form.valorParceiro) || 0,
            imposto: Number(form.imposto) || 0,
            colaboradorId: form.colaboradorId,
            liderId: form.liderId,
          },
        });
      }}
    >
      <h3 className="panel-title" style={{ gridColumn: "1 / -1", marginBottom: 0 }}>Dados da operação</h3>
      <Field label="Número da operação">
        <TextInput value={form.numero} onChange={(e) => setForm({ ...form, numero: e.target.value })} required />
      </Field>
      <Field label="Instituição financeira">
        <Select value={form.instituicaoId} onChange={(e) => setForm({ ...form, instituicaoId: e.target.value })} required>
          <option value="">Selecione</option>
          {db.institutions.map((b) => (
            <option key={b.id} value={b.id}>{b.nome}</option>
          ))}
        </Select>
      </Field>
      <Field label="Cliente">
        <Select value={form.clienteId} onChange={(e) => setForm({ ...form, clienteId: e.target.value })} required>
          <option value="">Selecione</option>
          {db.clients.map((c) => (
            <option key={c.id} value={c.id}>{c.nome}</option>
          ))}
        </Select>
      </Field>
      <Field label="Valor aprovado (cliente)">
        <MoneyInput value={form.valorAprovado} onChange={(e) => onValorAprovadoChange(e.target.value)} />
      </Field>
      <Field label="Valor a receber (instituição → Adventus)" hint={form.valorAprovado ? `${fmtPct(percentualReceita)} do valor aprovado` : null}>
        <MoneyInput value={form.valorAReceber} onChange={(e) => setForm({ ...form, valorAReceber: e.target.value })} />
      </Field>
      <Field label="Data de recebimento (instituição)">
        <TextInput type="date" value={form.dataRecebimentoBanco} onChange={(e) => setForm({ ...form, dataRecebimentoBanco: e.target.value })} />
      </Field>
      <Field label="Já recebido?">
        <label style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
          <input type="checkbox" checked={form.recebidoBanco} onChange={(e) => setForm({ ...form, recebidoBanco: e.target.checked })} />
          <span style={{ fontSize: 13, color: "var(--text)" }}>Sim, já caiu na conta</span>
        </label>
      </Field>

      <h3 className="panel-title" style={{ gridColumn: "1 / -1", marginTop: 16, marginBottom: 0 }}>Honorário do cliente</h3>
      <Field label="Modalidade (tipo de operação)">
        <TextInput value={form.modalidade} onChange={(e) => setForm({ ...form, modalidade: e.target.value })} placeholder="Ex.: Capital de Giro, Desconto de Recebíveis…" />
      </Field>
      <Field
        label="Parceiro estratégico"
        hint={selectedPartner ? `Repasse: ${fmtPct(selectedPartner.percentual)} sobre o honorário pago pelo cliente` : null}
      >
        <Select value={form.parceiroId} onChange={(e) => updateForm({ parceiroId: e.target.value })}>
          <option value="">Nenhum</option>
          {db.partners.map((p) => (
            <option key={p.id} value={p.id}>{p.nome}</option>
          ))}
        </Select>
      </Field>
      <Field label="Data do crédito">
        <TextInput type="date" value={form.dataCredito} onChange={(e) => setForm({ ...form, dataCredito: e.target.value })} />
      </Field>
      <Field label="Valor liberado da operação">
        <MoneyInput value={form.valorLiberado} onChange={(e) => updateForm({ valorLiberado: e.target.value })} />
      </Field>
      <Field label="Valor do honorário do cliente (bruto)" hint={form.valorLiberado ? `${fmtPct(pctHonorario)} do valor liberado` : null}>
        <MoneyInput value={form.valorHonorario} onChange={(e) => updateForm({ valorHonorario: e.target.value })} />
      </Field>
      <Field
        label="Valor do parceiro (repasse/débito)"
        hint={form.valorHonorario ? `${fmtPct(pctParceiro)} do honorário pago pelo cliente — pré-preenchido, edite se for exceção` : null}
      >
        <MoneyInput value={form.valorParceiro} onChange={(e) => setForm({ ...form, valorParceiro: e.target.value })} />
      </Field>
      <Field
        label="Imposto sobre o honorário (R$)"
        hint={`Padrão de ${fmtPct(db.metas?.impostoPadrao || 0)} sobre o bruto — pré-preenchido, edite se for exceção`}
      >
        <MoneyInput
          value={form.imposto}
          onChange={(e) => { setImpostoTocado(true); setForm({ ...form, imposto: e.target.value }); }}
        />
      </Field>
      <Field label="Colaborador responsável">
        <Select value={form.colaboradorId} onChange={(e) => setForm({ ...form, colaboradorId: e.target.value })} required disabled={user.papel === "colaborador"}>
          <option value="">Selecione</option>
          {colaboradorOptions.map((c) => (
            <option key={c.id} value={c.id}>{c.nome}</option>
          ))}
        </Select>
      </Field>
      <Field label="Líder responsável (comissão fixa de 3%)">
        <Select value={form.liderId} onChange={(e) => setForm({ ...form, liderId: e.target.value })} disabled={isSelfScoped}>
          <option value="">Nenhum</option>
          {db.collaborators.filter((c) => c.papel === "lider").map((c) => (
            <option key={c.id} value={c.id}>{c.nome}</option>
          ))}
        </Select>
      </Field>

      <h3 className="panel-title" style={{ gridColumn: "1 / -1", marginTop: 16, marginBottom: 0 }}>
        TAC — Capital de Giro / Desconto de Recebíveis <span style={{ fontWeight: 400, fontSize: 12, color: "var(--text-muted)" }}>(opcional)</span>
      </h3>
      <Field label="Esta operação tem TAC?">
        <label style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
          <input type="checkbox" checked={form.tacAtivo} onChange={(e) => setForm({ ...form, tacAtivo: e.target.checked })} />
          <span style={{ fontSize: 13, color: "var(--text)" }}>Sim, preencher TAC</span>
        </label>
      </Field>
      {form.tacAtivo && (
        <>
          <Field label="TAC — valor geral">
            <MoneyInput value={form.tacValorGeral} onChange={(e) => setForm({ ...form, tacValorGeral: e.target.value })} />
          </Field>
          <Field label="Parceiro da TAC">
            <TextInput value={form.tacParceiroNome} onChange={(e) => setForm({ ...form, tacParceiroNome: e.target.value })} />
          </Field>
          <Field label="% Adventus na TAC">
            <TextInput type="number" step="0.01" value={form.tacPctAdventus} onChange={(e) => setForm({ ...form, tacPctAdventus: e.target.value })} />
          </Field>
          <Field label={`% ${form.tacParceiroNome || "parceiro"} na TAC (automático)`}>
            <TextInput value={fmtPct(tacPctParceiro)} disabled />
          </Field>
        </>
      )}

      <div className="preview-box" style={{ gridColumn: "1 / -1" }}>
        <strong>Resumo e prévia completa da operação</strong>
        <div className="preview-grid">
          <span>Receita da instituição (banco)</span>
          <span className="num">{fmtBRL(Number(form.valorAReceber) || 0)}</span>
          <span>Honorário líquido deste lançamento</span>
          <span className="num">{fmtBRL(liquidoPreview)}</span>
          <span>Comissão do líder estimada (3%)</span>
          <span className="num">{form.liderId ? fmtBRL(comissaoLiderPreview) : "—"}</span>
          {form.tacAtivo && (
            <>
              <span>TAC — {fmtBRL(Number(form.tacValorGeral) || 0)} total</span>
              <span className="num">
                Adventus {fmtBRL(tacValorAdventus)} · {form.tacParceiroNome} {fmtBRL(tacValorParceiro)}
              </span>
            </>
          )}
        </div>
        {form.colaboradorId && (
          <>
            <strong style={{ marginTop: 12 }}>Projeção da meta mensal do consultor ({monthLabel(ym)})</strong>
            <div className="preview-grid">
              <span>Honorário bruto acumulado no mês</span>
              <span className="num">{fmtBRL(brutoAcumulado)}</span>
              <span>% da meta atingido</span>
              <span className="num">{metaMensal > 0 ? fmtPct(pctMeta) : "cadastre a meta em Cadastros"}</span>
              <span>Faixa de comissão projetada</span>
              <span className="num">{rateProjetada !== null ? fmtPct(rateProjetada) : "—"}</span>
              <span>Comissão do consultor projetada no mês</span>
              <span className="num">{comissaoProjetada !== null ? fmtBRL(comissaoProjetada) : "—"}</span>
              <span>Bônus por meta/super meta</span>
              <span className="num">{bonusProjetado > 0 ? fmtBRL(bonusProjetado) : "—"}</span>
            </div>
            <p className="panel-note" style={{ margin: "8px 0 0" }}>
              A comissão final do consultor é apurada uma vez por mês sobre o total do período — veja em Painel geral → Comissão mensal por consultor.
            </p>
          </>
        )}
      </div>

      <div className="form-actions">
        <Btn type="submit">
          <Check size={14} /> Salvar operação completa
        </Btn>
        <Btn type="button" variant="ghost" onClick={onCancel}>
          Cancelar
        </Btn>
      </div>
    </form>
  );
}

function OperacoesPage({ db, mutate, user }) {
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [search, setSearch] = useState("");
  const institutionName = (id) => db.institutions.find((b) => b.id === id)?.nome || "—";
  const clientName = (id) => db.clients.find((c) => c.id === id)?.nome || "—";
  const collabName = (id) => db.collaborators.find((c) => c.id === id)?.nome || "—";

  const visibleOps = useMemo(() => {
    const visibleHonSet = new Set(visibleHonorarios(db, user).map((h) => h.operacaoId));
    return user.papel === "diretora" ? db.operations : db.operations.filter((o) => visibleHonSet.has(o.id) || !db.honorarios.some((h) => h.operacaoId === o.id));
  }, [db, user]);

  const save = (data) => {
    mutate((d) => {
      let operations, honorarios;
      if (editingId) {
        operations = d.operations.map((o) => (o.id === editingId ? { ...o, ...data.operacao } : o));
        const existingHon = d.honorarios.find((h) => h.operacaoId === editingId);
        honorarios = existingHon
          ? d.honorarios.map((h) => (h.id === existingHon.id ? { ...h, ...data.honorario } : h))
          : [...d.honorarios, { id: uid(), operacaoId: editingId, ...data.honorario }];
      } else {
        const newId = uid();
        operations = [...d.operations, { id: newId, ...data.operacao }];
        honorarios = [...d.honorarios, { id: uid(), operacaoId: newId, ...data.honorario }];
      }
      return { ...d, operations, honorarios };
    });
    setShowForm(false);
    setEditingId(null);
  };

  const editingOp = editingId ? db.operations.find((o) => o.id === editingId) : null;
  const editingHon = editingId ? db.honorarios.find((h) => h.operacaoId === editingId) : null;

  const term = search.trim().toLowerCase();
  const filteredOperations = term
    ? visibleOps.filter((o) => `${o.numero} ${institutionName(o.instituicaoId)} ${clientName(o.clienteId)}`.toLowerCase().includes(term))
    : visibleOps;

  return (
    <div>
      <div className="page-header">
        <h2>Operações</h2>
        <Btn onClick={() => { setEditingId(null); setShowForm(!showForm || editingId !== null); }}>
          <Plus size={14} /> Nova operação
        </Btn>
      </div>
      {(showForm || editingId) && (
        <OperacaoCompletaForm db={db} editingOp={editingOp} editingHon={editingHon} user={user} onSave={save} onCancel={() => { setShowForm(false); setEditingId(null); }} />
      )}
      {db.operations.length > 0 && (
        <div className="search-box">
          <Search size={14} />
          <input className="input" placeholder="Buscar por nº, instituição ou cliente…" value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
      )}
      {visibleOps.length === 0 ? (
        <EmptyState text="Nenhuma operação lançada ainda." />
      ) : filteredOperations.length === 0 ? (
        <EmptyState text="Nenhuma operação encontrada para essa busca." />
      ) : (
        <div className="table-scroll">
          <table className="table">
            <thead>
              <tr>
                <th>Nº operação</th>
                <th>Instituição</th>
                <th>Cliente</th>
                <th>Data crédito</th>
                <th>Banco a receber</th>
                <th>Recebido?</th>
                <th>Honorário líquido</th>
                <th>Colaborador</th>
                <th>Comissão líder</th>
                <th>TAC</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {filteredOperations.map((o) => {
                const hon = db.honorarios.find((h) => h.operacaoId === o.id);
                const c = hon ? computeHonorario(hon) : null;
                return (
                  <tr key={o.id}>
                    <td>{o.numero}</td>
                    <td>{institutionName(o.instituicaoId)}</td>
                    <td>{clientName(o.clienteId)}</td>
                    <td>{hon?.dataCredito ? new Date(hon.dataCredito + "T00:00:00").toLocaleDateString("pt-BR") : "—"}</td>
                    <td className="num">{fmtBRL(o.valorAReceber)}</td>
                    <td>
                      <Tag tone={o.recebidoBanco ? "positive" : null}>{o.recebidoBanco ? "Recebido" : "A receber"}</Tag>
                    </td>
                    <td className="num strong">{c ? fmtBRL(c.liquido) : "—"}</td>
                    <td>{hon ? collabName(hon.colaboradorId) : "—"}</td>
                    <td className="num positive">{c && hon?.liderId ? fmtBRL(c.comissaoLider) : "—"}</td>
                    <td className="num">{o.tacAtivo ? fmtBRL(o.tacValorGeral) : "—"}</td>
                    <td className="actions">
                      <RowActions
                        onEdit={() => { setEditingId(o.id); setShowForm(true); }}
                        onDelete={() =>
                          mutate((d) => ({
                            ...d,
                            operations: d.operations.filter((x) => x.id !== o.id),
                            honorarios: d.honorarios.filter((h) => h.operacaoId !== o.id),
                          }))
                        }
                      />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function computeHonorario(h) {
  const liquido = honorarioLiquido(h);
  const comissaoLider = h.liderId ? liquido * 0.03 : 0;
  // "resultado" aqui é parcial (não inclui a comissão do consultor, que agora é
  // apurada mensalmente — veja computeMonthlyConsultor / o painel de Comissão Mensal).
  return { liquido, comissaoLider, resultado: liquido - comissaoLider };
}

/* ----------------------------------------------------------------------------
   Financeiro interno — DRE simplificado (regime de competência) e Fluxo de
   caixa consolidado (regime de caixa). As duas visões usam a MESMA base de
   dados de receita (honorários/operações) já existente, sem duplicar
   lançamentos: a diferença é só a data usada para posicionar cada valor no
   tempo.
     - DRE: por dataCredito do honorário (quando o crédito foi aprovado/gerado).
     - Fluxo de caixa: por dataRecebimento/dataPagamento (quando o dinheiro de
       fato entrou ou saiu do caixa).
---------------------------------------------------------------------------- */

// resultado do mês pelo regime de competência: tudo que "pertence" ao mês do
// crédito, esteja o dinheiro recebido ou não — é a foto de resultado da
// empresa, comparável mês a mês.
function dreMes(db, ym) {
  const honorariosMes = db.honorarios.filter((h) => monthKey(h.dataCredito) === ym);
  const receitaHonorarioBruto = honorariosMes.reduce((s, h) => s + (Number(h.valorHonorario) || 0), 0);
  const repasseParceiros = honorariosMes.reduce((s, h) => s + (Number(h.valorParceiro) || 0), 0);
  const impostos = honorariosMes.reduce((s, h) => s + (Number(h.imposto) || 0), 0);
  const comissaoLideres = honorariosMes.reduce((s, h) => s + computeHonorario(h).comissaoLider, 0);

  // receita das instituições financeiras (repasse) e TAC: como a operação não
  // tem data própria, usa-se a data do crédito do honorário vinculado a ela
  // (evita contar a mesma operação duas vezes se por acaso houver mais de um
  // honorário apontando pra ela).
  let receitaInstituicoes = 0;
  let tacAdventus = 0;
  const opsContadas = new Set();
  honorariosMes.forEach((h) => {
    const op = db.operations.find((o) => o.id === h.operacaoId);
    if (op && !opsContadas.has(op.id)) {
      opsContadas.add(op.id);
      receitaInstituicoes += Number(op.valorAReceber) || 0;
      if (op.tacAtivo) tacAdventus += ((Number(op.tacValorGeral) || 0) * (Number(op.tacPctAdventus) || 0)) / 100;
    }
  });

  // comissão dos consultores: mesma apuração mensal usada no Painel geral —
  // um cálculo por (consultor, mês), não por lançamento.
  const consultorIds = [...new Set(honorariosMes.map((h) => h.colaboradorId).filter(Boolean))];
  const comissaoConsultores = consultorIds.reduce((s, cid) => s + computeMonthlyConsultor(db, cid, ym).total, 0);

  const despesasMes = (db.despesas || []).filter((d) => monthKey(d.dataVencimento) === ym);
  const despesasFixas = despesasMes.filter((d) => despesaCategoriaTipo(db, d.categoriaId) === "fixa").reduce((s, d) => s + (Number(d.valor) || 0), 0);
  const despesasVariaveis = despesasMes.filter((d) => despesaCategoriaTipo(db, d.categoriaId) === "variavel").reduce((s, d) => s + (Number(d.valor) || 0), 0);
  const despesasOperacionais = despesasFixas + despesasVariaveis;

  const receitaCredito = receitaCreditoMes(db, ym);
  const receitaBruta = receitaHonorarioBruto + receitaInstituicoes + tacAdventus + receitaCredito;
  const deducoes = repasseParceiros + impostos;
  const receitaLiquida = receitaBruta - deducoes;
  const custosComissoes = comissaoLideres + comissaoConsultores;
  const resultadoOperacional = receitaLiquida - custosComissoes - despesasOperacionais;
  const margemLiquida = receitaBruta > 0 ? (resultadoOperacional / receitaBruta) * 100 : 0;

  return {
    ym,
    receitaHonorarioBruto,
    receitaInstituicoes,
    tacAdventus,
    receitaCredito,
    receitaBruta,
    repasseParceiros,
    impostos,
    deducoes,
    receitaLiquida,
    comissaoLideres,
    comissaoConsultores,
    custosComissoes,
    despesasFixas,
    despesasVariaveis,
    despesasOperacionais,
    resultadoOperacional,
    margemLiquida,
    operacoes: honorariosMes.length,
  };
}

// resultado do mês pelo regime de caixa: só o que de fato entrou/saiu do
// caixa naquele mês, independente de a que mês de competência pertence.
function fluxoCaixaMes(db, ym) {
  const entradasHonorarios = (db.recebimentos || [])
    .filter((r) => r.tipo === "cliente" && r.recebido && monthKey(r.dataRecebimento) === ym)
    .reduce((s, r) => s + (Number(r.valor) || 0), 0);
  const entradasBancoAgenda = (db.recebimentos || [])
    .filter((r) => r.tipo === "banco" && r.recebido && monthKey(r.dataRecebimento) === ym)
    .reduce((s, r) => s + (Number(r.valor) || 0), 0);
  // operações com o repasse do banco marcado como recebido direto na tela de
  // Operações, sem passar por um lançamento manual na Agenda — evita contar
  // duas vezes quando as duas fontes apontam pra mesma operação.
  const opsComAgenda = new Set((db.recebimentos || []).filter((r) => r.tipo === "banco").map((r) => r.refId));
  const entradasBancoDireto = (db.operations || [])
    .filter((o) => o.recebidoBanco && monthKey(o.dataRecebimentoBanco) === ym && !opsComAgenda.has(o.id))
    .reduce((s, o) => s + (Number(o.valorAReceber) || 0), 0);

  // crédito próprio: entra o que foi pago nas parcelas; sai o principal liberado
  const cred = creditoCaixaMes(db, ym);
  const entradas = entradasHonorarios + entradasBancoAgenda + entradasBancoDireto + cred.entradas;
  const saidas =
    (db.despesas || [])
      .filter((d) => d.pago && monthKey(d.dataPagamento) === ym)
      .reduce((s, d) => s + (Number(d.valor) || 0), 0) + cred.saidas;

  return { ym, entradasHonorarios, entradasBanco: entradasBancoAgenda + entradasBancoDireto, entradasCredito: cred.entradas, saidasCredito: cred.saidas, entradas, saidas, saldo: entradas - saidas };
}

// últimos N meses (yyyy-mm) até o mês corrente, mais antigo primeiro
function lastMonths(n) {
  const out = [];
  const now = new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    out.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
  }
  return out;
}

/* ---------------------------- Agenda de recebimentos ---------------------------- */

// Espelho automático das OPERAÇÕES na agenda. Nada é gravado: as linhas são
// derivadas a cada render, então mudar data/valor na operação já muda a agenda.
//  - repasse da instituição: valorAReceber na dataRecebimentoBanco (recebido = op.recebidoBanco)
//  - honorário do cliente: valorHonorario na dataCredito
// Um lançamento manual para o mesmo vínculo (parcelas, histórico) tem prioridade e
// suprime o espelho daquele vínculo, evitando contar duas vezes.
function agendaAutomatica(db) {
  const manuais = db.recebimentos || [];
  const bancoManual = new Set(manuais.filter((r) => r.tipo === "banco").map((r) => r.refId));
  const clienteManual = new Set(manuais.filter((r) => r.tipo === "cliente").map((r) => r.refId));
  const out = [];
  (db.operations || []).forEach((o) => {
    const valor = Number(o.valorAReceber) || 0;
    if (!o.dataRecebimentoBanco || valor <= 0 || bancoManual.has(o.id)) return;
    out.push({
      id: `auto-banco-${o.id}`, auto: true, tipo: "banco", refId: o.id,
      descricao: "Repasse da instituição", valor,
      dataVencimento: o.dataRecebimentoBanco, recebido: !!o.recebidoBanco,
      dataRecebimento: o.recebidoBanco ? o.dataRecebimentoBanco : null,
    });
  });
  (db.honorarios || []).forEach((h) => {
    const valor = Number(h.valorHonorario) || 0;
    if (!h.dataCredito || valor <= 0 || clienteManual.has(h.id)) return;
    out.push({
      id: `auto-cliente-${h.id}`, auto: true, tipo: "cliente", refId: h.id,
      descricao: "Honorário do cliente", valor,
      dataVencimento: h.dataCredito, recebido: false, dataRecebimento: null,
    });
  });
  return out;
}

function agendaCompleta(db) {
  return [...(db.recebimentos || []), ...agendaAutomatica(db)];
}

function RecebimentoForm({ db, editing, onSave, onCancel }) {
  const [form, setForm] = useState(
    editing || { tipo: "cliente", refId: "", descricao: "", valor: "", dataVencimento: todayISO() }
  );

  return (
    <form
      className="panel form-grid"
      onSubmit={(e) => {
        e.preventDefault();
        if (!form.refId || !form.valor || !form.dataVencimento) return;
        onSave({ ...form, valor: Number(form.valor), recebido: !!form.recebido, dataRecebimento: form.recebido ? form.dataRecebimento || form.dataVencimento : null });
      }}
    >
      <Field label="Tipo de recebimento">
        <Select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value, refId: "" })}>
          <option value="cliente">Honorário do cliente</option>
          <option value="banco">Receita da instituição financeira</option>
        </Select>
      </Field>
      <Field label={form.tipo === "cliente" ? "Honorário vinculado" : "Operação vinculada"}>
        <Select value={form.refId} onChange={(e) => setForm({ ...form, refId: e.target.value })} required>
          <option value="">Selecione</option>
          {form.tipo === "cliente"
            ? db.honorarios.map((h) => (
                <option key={h.id} value={h.id}>
                  {db.clients.find((c) => c.id === h.clienteId)?.nome || "—"} · {fmtBRL(h.valorHonorario)}
                </option>
              ))
            : db.operations.map((o) => (
                <option key={o.id} value={o.id}>
                  {o.numero} · {fmtBRL(o.valorAReceber)}
                </option>
              ))}
        </Select>
      </Field>
      <Field label="Descrição (opcional)">
        <TextInput value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} placeholder="Ex.: 1ª parcela" />
      </Field>
      <Field label="Valor">
        <MoneyInput value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} required />
      </Field>
      <Field label="Data de vencimento">
        <TextInput type="date" value={form.dataVencimento} onChange={(e) => setForm({ ...form, dataVencimento: e.target.value })} required />
      </Field>
      <label className="checkbox-row">
        <input type="checkbox" checked={!!form.recebido} onChange={(e) => setForm({ ...form, recebido: e.target.checked, dataRecebimento: form.dataRecebimento || form.dataVencimento })} />
        <span>Já foi recebido (lançamento retroativo)</span>
      </label>
      {form.recebido && (
        <Field label="Data do recebimento">
          <TextInput type="date" value={form.dataRecebimento || ""} onChange={(e) => setForm({ ...form, dataRecebimento: e.target.value })} required />
        </Field>
      )}
      <div className="form-actions">
        <Btn type="submit">
          <Check size={14} /> Salvar
        </Btn>
        <Btn type="button" variant="ghost" onClick={onCancel}>
          Cancelar
        </Btn>
      </div>
    </form>
  );
}

function AgendaPage({ db, mutate, user }) {
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [filter, setFilter] = useState("todos");

  const visibleHon = visibleHonorarios(db, user);
  const visibleHonIds = new Set(visibleHon.map((h) => h.id));
  const list = agendaCompleta(db).filter((r) => (r.tipo === "cliente" ? visibleHonIds.has(r.refId) : true));

  // dar baixa numa linha automática: o repasse grava na própria operação; o
  // honorário vira um recebimento real (que passa a valer no fluxo de caixa).
  const baixarAuto = (r, data) =>
    mutate((d) => {
      if (r.tipo === "banco") {
        return { ...d, operations: d.operations.map((o) => (o.id === r.refId ? { ...o, recebidoBanco: true, dataRecebimentoBanco: data } : o)) };
      }
      return {
        ...d,
        recebimentos: [
          ...d.recebimentos,
          { id: uid(), tipo: "cliente", refId: r.refId, descricao: r.descricao, valor: r.valor, dataVencimento: r.dataVencimento, recebido: true, dataRecebimento: data },
        ],
      };
    });

  const refLabel = (r) => {
    if (r.tipo === "cliente") {
      const h = db.honorarios.find((x) => x.id === r.refId);
      return h ? `Honorário · ${db.clients.find((c) => c.id === h.clienteId)?.nome || "—"}` : "Honorário removido";
    }
    const o = db.operations.find((x) => x.id === r.refId);
    return o ? `Operação · ${o.numero}` : "Operação removida";
  };

  const withStatus = list.map((r) => ({ ...r, status: recebimentoStatus(r) })).sort((a, b) => a.dataVencimento.localeCompare(b.dataVencimento));
  const counts = withStatus.reduce((acc, r) => ({ ...acc, [r.status]: (acc[r.status] || 0) + 1 }), {});
  const filtered = filter === "todos" ? withStatus : withStatus.filter((r) => r.status === filter);

  const save = (data) => {
    mutate((d) => {
      if (editingId) return { ...d, recebimentos: d.recebimentos.map((r) => (r.id === editingId ? { ...r, ...data } : r)) };
      return { ...d, recebimentos: [...d.recebimentos, { id: uid(), recebido: false, dataRecebimento: null, ...data }] };
    });
    setShowForm(false);
    setEditingId(null);
  };
  const editing = editingId ? db.recebimentos.find((r) => r.id === editingId) : null;

  const filters = [
    { id: "todos", label: "Todos" },
    { id: "atrasado", label: `Atrasados (${counts.atrasado || 0})` },
    { id: "hoje", label: `Hoje (${counts.hoje || 0})` },
    { id: "proximo", label: `Próximos 7 dias (${counts.proximo || 0})` },
    { id: "futuro", label: "Futuros" },
    { id: "recebido", label: "Recebidos" },
  ];

  return (
    <div>
      <div className="page-header">
        <div>
          <h2>Agenda de recebimentos</h2>
          <p className="muted" style={{ margin: "2px 0 0", fontSize: 12.5 }}>
            Os recebimentos futuros das Operações (repasse da instituição e honorário do cliente) aparecem aqui automaticamente, nas datas cadastradas na operação.
            Use "Novo recebimento" só para parcelas ou lançamentos extras.
          </p>
        </div>
        <Btn onClick={() => { setEditingId(null); setShowForm(!showForm || editingId !== null); }}>
          <Plus size={14} /> Novo recebimento
        </Btn>
      </div>

      {(counts.atrasado || counts.hoje) && (
        <div className="alert-banner">
          <Bell size={16} />
          <span>
            {counts.atrasado ? `${counts.atrasado} recebimento(s) atrasado(s)` : ""}
            {counts.atrasado && counts.hoje ? " · " : ""}
            {counts.hoje ? `${counts.hoje} vencendo hoje` : ""}
          </span>
        </div>
      )}

      {(showForm || editingId) && <RecebimentoForm db={db} editing={editing} onCancel={() => { setShowForm(false); setEditingId(null); }} onSave={save} />}

      <div className="subtabs">
        {filters.map((f) => (
          <button key={f.id} className={`subtab ${filter === f.id ? "subtab-active" : ""}`} onClick={() => setFilter(f.id)}>
            {f.label}
          </button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <EmptyState text="Nenhum recebimento nesse filtro." />
      ) : (
        <table className="table">
          <thead>
            <tr>
              <th>Vencimento</th>
              <th>Referência</th>
              <th>Descrição</th>
              <th>Valor</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((r) => (
              <tr key={r.id}>
                <td>{new Date(r.dataVencimento + "T00:00:00").toLocaleDateString("pt-BR")}</td>
                <td>{refLabel(r)}</td>
                <td>
                  {r.descricao || "—"}
                  {r.auto && <Tag>Automático</Tag>}
                </td>
                <td className="num">{fmtBRL(r.valor)}</td>
                <td>
                  <Tag tone={r.status === "atrasado" ? "negative" : r.status === "recebido" ? "positive" : r.status === "hoje" ? "brass" : null}>
                    {STATUS_LABEL[r.status]}
                  </Tag>
                </td>
                <td className="actions">
                  {!r.recebido && (
                    <DataConfirmBtn
                      label="Marcar recebido"
                      onConfirm={(data) =>
                        r.auto
                          ? baixarAuto(r, data)
                          : mutate((d) => ({ ...d, recebimentos: d.recebimentos.map((x) => (x.id === r.id ? { ...x, recebido: true, dataRecebimento: data } : x)) }))
                      }
                    />
                  )}
                  {r.auto ? (
                    <span className="muted" style={{ fontSize: 11.5 }}>edite em Operações</span>
                  ) : (
                    <RowActions
                      onEdit={() => { setEditingId(r.id); setShowForm(true); }}
                      onDelete={() => mutate((d) => ({ ...d, recebimentos: d.recebimentos.filter((x) => x.id !== r.id) }))}
                    />
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

/* ---------------------------- Financeiro interno ---------------------------- */

// Botão "Marcar pago/recebido" que pede a data efetiva (padrão: hoje), para
// permitir baixas retroativas — o caixa usa essa data, não a do clique.
function DataConfirmBtn({ label, onConfirm }) {
  const [open, setOpen] = useState(false);
  const [data, setData] = useState(todayISO());
  if (!open) {
    return (
      <button className="btn btn-ghost btn-sm" onClick={() => { setData(todayISO()); setOpen(true); }}>
        {label}
      </button>
    );
  }
  return (
    <span style={{ display: "inline-flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
      <input className="input" type="date" title="Data efetiva" value={data} onChange={(e) => setData(e.target.value)} style={{ width: 140 }} />
      <button className="btn btn-primary btn-sm" disabled={!data} onClick={() => { onConfirm(data); setOpen(false); }}>
        Confirmar
      </button>
      <button className="btn btn-ghost btn-sm" onClick={() => setOpen(false)}>
        Cancelar
      </button>
    </span>
  );
}

